INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしだって\nやるときはやるよ！", 102601, "2020/04/30 12:00:00", 24, 0, "リン", "2030/12/17 14:59:59", 0.0, 1, 24001, 1, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("ふぅ…\nこれであたしの仕事は\n終わりだね", 102601, "2020/04/30 12:00:00", 24, 1, "リン", "2030/12/17 14:59:59", 0.0, 1, 24002, 1, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("終わった終わった\n一人でもなんとか\nなるもんだね", 102601, "2020/04/30 12:00:00", 24, 2, "リン", "2030/12/17 14:59:59", 0.0, 1, 24003, 1, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("やったね！\nこれでようやく\nサボれるよ…", 102601, "2020/04/30 12:00:00", 24, 3, "リン", "2030/12/17 14:59:59", 0.0, 2, 24004, 2, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 102601, "2020/04/30 12:00:00", 24, 4, "リン", "2030/12/17 14:59:59", 0.0, 1, 24005, 1, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしを敵に回した\n恐ろしさ\n思い知ったか！", 102601, "2020/04/30 12:00:00", 24, 5, "リン", "2030/12/17 14:59:59", 0.0, 2, 24006, 2, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("あたしも意外と\nやるもんでしょ？", 102601, "2020/04/30 12:00:00", 24, 6, "リン", "2030/12/17 14:59:59", 0.0, 2, 24007, 2, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("疲れた…\nねずみの逃げ足\n速すぎるよ…", 102601, "2020/04/30 12:00:00", 24, 7, "リン", "2030/12/17 14:59:59", 0.0, 4, 24008, 4, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("このままじゃ\nまっひ～に\n叱られちゃうよ", 102601, "2020/04/30 12:00:00", 24, 8, "リン", "2030/12/17 14:59:59", 0.0, 4, 24009, 4, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("まじめに\nやったんだけどな…\n悔しいな～", 102601, "2020/04/30 12:00:00", 24, 9, "リン", "2030/12/17 14:59:59", 0.0, 4, 24010, 4, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("やられた…\nねずみって意外と\nてごわいね", 102601, "2020/04/30 12:00:00", 24, 10, "リン", "2030/12/17 14:59:59", 0.0, 4, 24011, 4, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("おのれ～\nあたしのチーズを\n盗みやがって～！", 102601, "2020/04/30 12:00:00", 24, 11, "リン", "2030/12/17 14:59:59", 0.0, 4, 24012, 4, 0.0, 0.0, 10040);
INSERT INTO `v1_b099ccd7113dbba83b903ede6d4982ffadb50105c1b8ef967cdc911cef72c2d0` VALUES ("疲れた…\nけど、次こそは\n守り抜くよ…", 102601, "2020/04/30 12:00:00", 24, 12, "リン", "2030/12/17 14:59:59", 0.0, 4, 24013, 1, 1.81, 0.0, 10040);
